import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"漢上易傳卷十","description":"漢上易傳 - 漢上易傳卷十","frontmatter":{"title":"漢上易傳卷十","description":"漢上易傳 - 漢上易傳卷十"},"headers":[],"relativePath":"classics/hanshang/011.md","filePath":"classics/hanshang/011.md"}'),c={name:"classics/hanshang/011.md"};function o(l,e,i,d,p,h){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"漢上易傳卷十",tabindex:"-1"},[r("漢上易傳卷十 "),a("a",{class:"header-anchor",href:"#漢上易傳卷十","aria-label":"Permalink to “漢上易傳卷十”"},"​")],-1),a("p",null,"文王作易，以乾、坤、坎、離為上篇之用，以艮、兌、震、巽為下篇之用。上篇終於坎、離，下篇終於既、濟、未濟、頤、大過、小過、中孚，為二篇之正。乾、坤者，易之本；坎、離者，乾、坤之用。離肖乾，坎肖坤，中孚肖乾，小過肖坤，頤肖離，大過肖坎。既、濟坎、離之交，未濟坎、離之合。坎、離所以為乾、坤用者，得天地之中也。斯聖人酬酢不倚，千變萬化不離乎其中歟？康節曰：至哉，文王之作易也，其得天地之用乎？至夫子序卦，然後明生生不窮，而天地之蘊盡矣。故太玄準之以玄圖有天地，然後萬物生焉。盈天地之間者唯萬物，故受之以屯。屯者，盈也。屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。物稚不可不養也，故受之以需。需者，飲食之道也。飲食必有訟，故受之以訟。訟必有眾起，故受之以師。師者，眾也。眾必有所比，故受之以比。比者，比也。比必有所畜，故受之以小畜。物畜然後有禮，故受之以履。履而泰然後安、故受之以泰。泰者，通也。物不可以終通、故受之以否。物不可以終否、故受之以同人。與人同者、物必歸焉、故受之以大有。有大者不可以盈、故受之以謙。有大而能謙必豫、故受之以豫。豫必有隨、故受之以隨。以喜隨人者必有事、故受之以蠱。蠱者，事也。有事而後可大，故受之以臨。臨者，大也。物大然後可觀，故受之以觀。可觀而後有所合，故受之以噬嗑。嗑者，合也。物不可以苟合而巳，故受之以賁。賁者，飾也。致飾然後亨則盡矣，故受之以剝。剝者，剝也。物不可以終盡，剝，窮上反下、故受之以復。復則不妄矣、故受之以無妄。有無妄然後可畜、故受之以大畜。物畜然後可養、故受之以頤。頤者、養也。不養則不可動、故受之以大過。物不可以終過、故受之以坎。坎者、陷也。陷必有所麗、故受之以離。離者、麗也。上篇以乾、坤、坎、離為用，天地之生萬物也，而有艮、兌、震、巽焉，天地萬物具而人道備矣。下篇以艮、兌、震、巽為用，有萬物而後男女夫婦也，而有乾、坤、坎、離焉，人道備而天地萬物備矣。故曰三才同科，厚薄相劘。韓康伯不領此旨，謂豈有天道人事偏於上下哉。讀序卦而不察者也。雲行雷動，動必滿盈，故曰屯者，盈也。震者，物之始生，坎者，難也，故曰屯者物之始生也。蒙，冥昧也。物生者必始於冥昧，勾萌胎夘是也。故次之以蒙。蒙，童蒙也。物如此稚也，物稚而無以養之，則夭閼不遂。蓄德養才者亦然，故次之以需、震、坎為酒，兌為口。有飲食之道，飲食所以養也。飲食必有訟。乾餱以愆，豕酒生禍。有血氣者必有爭心。故次之以訟。訟者兩辭，必以眾起，故次之以師。師，眾也。眾不能以治眾，治眾者至寡也。眾之所以比，執一以御之，則眾治矣。故以次之以比。比，相親比也。彼來比我，我必蓄之，故次之以小畜。物畜聚，然後有上下尊卑之等。上下尊卑，所謂禮也，故次之以履。禮者，履而行之者也。所履者，君子大道，則其心泰然而安，故次之以泰。泰者，萬物通也。物終通則無節，故次之以否。否，塞也。物終否則乖異不相為用，故次之以同人。同人者，與人同也。與人同者，物必歸焉。舜大王是巳，故次之以大有。認物之歸為已有者必驕，驕則亢滿，大復為累矣。有大者不可盈也，故次之以謙。物歸之矣，又持之以謙，猶富而守之以儉，豈不有餘裕哉。有大而能謙者，必暇豫也，故次之以豫事。豫立則動而不跲，眾必隨之，故次之以隨。好上人者，人之情也。以喜隨人，必有所事。臣事君，子事父，婦事夫，弟子事師，非樂於所事者，其肯隨乎？故次之以蠱。蠱者，事壞而後有事者也。韓康伯曰：可大之業，由事以生。臨者，以大臨小也。故次之以臨。觀者，自下觀上，物大然後可觀，是以王尚大，故次之以觀。在上而無可觀，則在下引而去矣。非可觀，其能有合乎？故次之以噬嗑。噬嗑者，噬而合者也。物不可以苟合，苟合者，其終則離，必致飾焉，故次之以賁。賁、陰陽相飾也。致飾然後物亨。亨則盡矣。無以復加、故次之以剝。剝者、剝也。此商周之末、所以不勝其弊、文之末流也。物窮則反、不可終盡。剝陽窮於上而終反於下、故次之以復。復天理則無妄。無妄則其動也天、故次之以無妄。然後物物循理、乃可大畜，故次之以大畜。前曰比，必有所畜者，比而後畜，其畜也小，故次之以小畜。物能畜止，然後可養，雖養虎不外是也，故次之以頤。頤者，觀人之養也，求口實以自養也。聖人養賢，賢人養德，不養之則不能動。大過者，動而大過乎物也，故次之以大過。而大過六爻，皆以居安不動為忌。君子之所以過者，時也。過而不巳則失中，失中則陷沒。坎，陷也。陷必有所附麗，乃能出險，故次之以離。離，麗也。一本雲：麗必有所感，故次之以鹹。鹹，感也。",-1),a("p",null,"有天地然後有萬物，有萬物然後有男女，有男女然後有夫婦。有夫婦然後有父子，有父子然後有君臣，有君臣然後有上下，有上下然後禮義有所錯。夫婦之道，不可以不久也，故受之以恆。恆者，久也。物不可以久居其所，故受之以遁。遁者，退也，故受之以大壯。物不可以終壯，故受之以晉。晉者，進也。進必有所傷，故受之以明夷。夷者，傷也。傷於外者必反於家，故受之以家人。家道窮必乖，故受之以睽。聧者，乖也。乖必有難，故受之以蹇。蹇者，難也。物不可以終難，故受之以解。解者，緩也。緩必有所失，故受之以損。損而不已，必益，故受之以益。益而不巳，必決，故受之以夬。夬者，決也。決必有遇，故受之以姤。姤者，遇也。物相遇而後聚，故受之以萃。萃者，聚也。聚而上者謂之升，故受之以升。升而不巳必困，故受之以困。困乎上者必反下，故受之以井。井道不可不革，故受之以革。革物者莫若鼎，故受之以鼎。主器者莫若長子，故受之以震。震者，動也。物不可以終動，止之，故受之以艮。艮者，止也。物不可以終止，故受之以漸。漸者，進也。進必有所歸，故受之以歸。妹得其所歸者必大，故受之以豐。豐者，大也。窮大者必失其居，故受之以旅。旅而無所容，故受之以巽。巽者，入也。入而後說之，故受之以兌。兌者，說也。說而後散之，故受之以渙。渙者，離也。物不可以終離，故受之以節。節而信之，故受之以中孚。有其信者必行之，故受之以小過。有過物者必濟，故受之以既。濟物不可窮也，故受之以未濟終焉。君子之道，造端乎夫婦，久於其道而後化，故次之以恆。恆，久也。進退升降，與時消息，不可久居其所而不去，故次之以遁。君子，萬物之主，終遁而不反，天地閉塞，故次之以大壯。大者壯則小者羸，可進之時也，故次之以晉。晉，日出地而進於晝也，進而不巳，傷之者至，故次之以明夷。明夷，日在地中，明有所傷也。物無不反其本者，疾痛則呼其父母，傷於外者，未有不反於內，故次之以家人。家人，內也。治家者剛柔有節，過剛則厲，過柔則瀆，無節則道窮而親族乖離，故次之以聧。聧者，水火乖也。乖離則情不通而難生，故次之以蹇。蹇者，行有難也。難極必解，無終難之理，故次之以解。解蹇，難解也。難解則舒緩。解者，蹇之反五，退而居二，緩也。緩則寬弛，必有所失，故次之以損。損，減也。減下而益上，有失之象。消久則息，損而不巳者必益，損益相反也，故次之以益。益久則盈，盈則必決，堤防是巳，故次之以夬。夬者，陽決陰也。決則分，分則相遇，故次之以姤。姤者，陰出而與陽相遇也。物以類相從，遇而後聚，非其類，雖同居不相遇，故次之以萃。萃，二陽聚也。物相崇聚，其勢必升，積土是已，故次之以升。升者，聚而上之謂也。升而不知反，則力窮而困，故次之以困。困乎上者，必反乎下，山剝是巳，故次之以井。井，在下者也。井久則穢濁不食。治井之道，革去其害井者而己。三代之革，其禮相困，損益可知也，故次之以革。鼎之革物，以水濟火而熟之。革物者莫如鼎，故次之以鼎。鼎，器也。主宗廟之器者莫如長子。震，長子也，故次之以震。震者，陽動於下也。物不可以終動，動極則止，故止之。艮者，一陽止於上也，故次之以艮。物不可以終止，止極則動，故次之以漸。漸者，進有序也，進必有所歸，盈科之水是也，故次之以歸妹。歸妹者，女之歸也。得其所歸者必大，海善下是也，故次之以豐。豐，大也。前曰與人同者，物必歸焉，故受之以大有。此曰得其歸者必大，大有次同人者，處大之道也。豐次歸妹者，致大之道也。巳大矣，而又窮之，必至於無所寄託而失其所居之常，非特大名大位然也。學亦如是，故次之以旅。旅者，君子之窮也。旅卦以柔順謙下為吉，否則無所容矣，故次之以巽。巽者，陰入於陽之下也。天地之澤，萬物禮義之說，人心不入則不說，故次之以兌。兌者，說見於外也。說之而後散之，則說道不勞，無所不說矣，故次之以渙。渙者，險難離散也。離者必聚，散者必合，物無終離者也。聚者離之節，合者，散之節。節之則無離散，故次之以節。天地之節，不可以不信，不信則無以成萬物，而況於人乎？飲食起居，身之節也。不信則致疾。尊卑長幼，家之節也，不信則召亂，故次之以中孚。中孚，信也。行者，足相過也。小過以陰過，陽有行之象，有其信者，必行中無所疑也，故次之以小過。物各有量，不過則不能相濟，所過大則其濟亦大，是以智周萬物，然後道濟天下，故次之以既濟，而止復入於未濟。物之相生，終不可窮，故以未濟終篇焉。周易序卦傳第十。",-1)])])}const f=s(c,[["render",o]]);export{_ as __pageData,f as default};
